def test_owner_mismatch():
    store = {}
    task = {'owner': 'alice', 'version': 1, 'job_text': 'foo', 'criteria_version': 1}
    profile = {'owner': 'alice', 'version': 1}

    def compute():
        return "result"

    # Correct call
    res = evaluate(store, task, profile, compute)
    assert res == "result"
    assert len(store) == 1

    # Wrong owner
    task_wrong_owner = {'owner': 'bob', 'version': 1, 'job_text': 'foo', 'criteria_version': 1}
    try:
        evaluate(store, task_wrong_owner, profile, compute)
        assert False, "Should have raised PermissionError"
    except PermissionError:
        pass

    # Version mismatch
    task_wrong_version = {'owner': 'alice', 'version': 2, 'job_text': 'foo', 'criteria_version': 1}
    res_none = evaluate(store, task_wrong_version, profile, compute)
    assert res_none is None
    assert len(store) == 1 # No side effects

    # Different job_text or criteria_version should create new entry
    task_new_job = {'owner': 'alice', 'version': 1, 'job_text': 'bar', 'criteria_version': 1}
    evaluate(store, task_new_job, profile, compute)
    assert len(store) == 2

    task_new_criteria = {'owner': 'alice', 'version': 1, 'job_text': 'foo', 'criteria_version': 2}
    evaluate(store, task_new_criteria, profile, compute)
    assert len(store) == 3

    # Exception from compute should not be cached
    store_exc = {}
    def error_compute():
        raise ValueError("Boom")

    try:
        evaluate(store_exc, task, profile, error_compute)
    except ValueError:
        pass
    assert len(store_exc) == 0

    # Verify re-call after exception works
    res = evaluate(store_exc, task, profile, lambda: "fixed")
    assert res == "fixed"
    assert len(store_exc) == 1

